func (a *App) maintenance(ctx context.Context) {
	// Once at startup, then every half hour.
	//
	// The ticker alone meant a deployment that restarts more often than every
	// thirty minutes never swept at all — and a rollout, a crash loop, or an
	// operator restarting to apply a setting are all exactly that. Measured on
	// a three-year database: audit rows 1,100 days old and request metrics 400
	// days old survived a restart under a 365-day and a 90-day policy, because
	// the first tick had not arrived yet and the process did not live to see
	// one. Retention that only holds for uptime longer than the sweep interval
	// is not retention.
	//
	// It also gives an operator who has just set a policy a way to apply it:
	// restart, rather than wait half an hour with nothing to watch.
	a.runMaintenance(ctx)
	ticker := time.NewTicker(30 * time.Minute)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			a.runMaintenance(ctx)
		}
	}
}

// runMaintenance is one sweep: everything the deployment throws away on a
// schedule, in one place that can be called.
//
// It used to be the body of the ticker loop, which meant four operator-settable
// retention policies — analytics, audit, import sources, login attempts — plus
// the session and OIDC cleanups had no way to run except waiting half an hour,
// and so had never run in a test. A DELETE that takes too much is the kind of
// mistake nobody reports, because what it removed is exactly what nobody is
// looking at any more.
func (a *App) runMaintenance(ctx context.Context) {
	_, _ = a.db.Exec(ctx, `DELETE FROM user_sessions WHERE expires_at < now(); DELETE FROM oidc_login_states WHERE expires_at < now()`)
	retention := a.settingInt(ctx, "analytics.retention_days", 90)
	// make_interval, not ($1 || ' days'). The concatenation makes PostgreSQL
	// infer $1 as text, pgx refuses to encode a Go int into it — "unable to
	// encode 30 into text format for text (OID 25)" — and the statement never
	// reaches the database. Discarded with `_, _ =`, so this table has never
	// been pruned on any deployment, whatever 분석 데이터 보관일 was set to.
	// The audit prune below has had the right form all along.
	if _, err := a.db.Exec(ctx, `DELETE FROM api_request_metrics WHERE bucket < now() - make_interval(days => $1)`, retention); err != nil {
		a.logger.Warn("prune request metrics", "error", err, "retentionDays", retention)
	}
	a.cleanupImportSources(ctx)
	a.cleanupAttachmentFiles(ctx)
	a.pruneLoginAttempts(ctx)
	// Zero means an operator has chosen to keep everything, so the trail is only
	// trimmed when a policy asked for it.
	if days := a.settingInt(ctx, "audit.retention_days", 365); days > 0 {
		if _, err := a.db.Exec(ctx, `DELETE FROM audit_logs WHERE created_at < now() - make_interval(days => $1)`, days); err != nil {
			a.logger.Warn("prune audit logs", "error", err)
		}
	}
}

func asString(value any) string { return strings.TrimSpace(fmt.Sprint(value)) }
func (a *App) deleteReport(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(w, r)
	if !ok {
		return
	}
	p := currentPrincipal(r.Context())
	version, err := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("version")))
	if err != nil || version < 1 {
		writeError(w, http.StatusBadRequest, "VERSION_REQUIRED", "삭제할 보고서 버전이 필요합니다.")
		return
	}
	tx, err := a.db.Begin(r.Context())
	if err != nil {
		writeError(w, 500, "DATABASE_ERROR", "보고서를 삭제할 수 없습니다.")
		return
	}
	defer tx.Rollback(r.Context())
	var ownerID int64
	var storedVersion int
	var week time.Time
	var status string
	err = tx.QueryRow(r.Context(), `SELECT user_id,version,week_start,status FROM weekly_reports WHERE id=$1 FOR UPDATE`, id).
		Scan(&ownerID, &storedVersion, &week, &status)
	// Same rule as editing: a missing report and somebody else's answer alike.
	if errors.Is(err, pgx.ErrNoRows) {
		writeError(w, http.StatusForbidden, "FORBIDDEN", "본인의 보고서만 삭제할 수 있습니다.")
		return
	}
	if err != nil {
		writeError(w, 500, "DATABASE_ERROR", "보고서를 삭제할 수 없습니다.")
		return
	}
	if ownerID != p.ID {
		writeError(w, http.StatusForbidden, "FORBIDDEN", "본인의 보고서만 삭제할 수 있습니다.")
		return
	}
	if storedVersion != version {
		// Here the advice to reload is the right one, and it says why: nothing
		// is being typed, and what would be deleted is no longer what the page
		// was showing when the reader decided to delete it.
		writeError(w, http.StatusConflict, "VERSION_CONFLICT",
			"이 보고서는 화면에 띄운 뒤 바뀌었습니다. 지우려던 것과 지금 저장된 것이 다를 수 있으니, 다시 불러와 확인한 뒤 삭제하세요.")
		return
	}
	if _, err = tx.Exec(r.Context(), `UPDATE report_candidates SET status='DETECTED',accepted_report_id=NULL,updated_at=now()
		WHERE accepted_report_id=$1 AND user_id=$2 AND status='ACCEPTED'`, id, p.ID); err != nil {
		writeError(w, 500, "DATABASE_ERROR", "보고서 연결 정보를 정리할 수 없습니다.")
		return
	}
	if _, err = tx.Exec(r.Context(), `DELETE FROM weekly_reports WHERE id=$1 AND user_id=$2`, id, p.ID); err != nil {
		writeError(w, 500, "DATABASE_ERROR", "보고서를 삭제할 수 없습니다.")
		return
	}
	if err = tx.Commit(r.Context()); err != nil {
		writeError(w, 500, "DATABASE_ERROR", "보고서를 삭제할 수 없습니다.")
		return
	}
	a.audit(r, p, "report.delete", "report", strconv.FormatInt(id, 10), map[string]any{"weekStart": week.Format("2006-01-02"), "status": status, "version": version})
	w.WriteHeader(http.StatusNoContent)
}

